(function () { 'use strict';
function create(ctx) {
const { E, bank, qmap, go, save, toast, modal, closeModal, icon } = ctx;
function runQuestions() {
    return (ctx.state.active?.questionIds || []).map(id => E.questionFor(qmap.get(id), ctx.state.active)).filter(Boolean);
  }

function start(mode, unitId = null, subject = null, force = false, difficulty = null) {
    if (!ctx.canEdit()) return;
    if (ctx.state.active && !force) {
      modal(`
        <button class="modal-close" data-action="close" aria-label="關閉">${icon('cross')}</button>
        <h2>上一張任務還在進行中</h2>
        <p>可以接著完成目前作答，或放下未交卷的答案，開啟新的挑戰。已交卷的成績與徽章會保留。</p>
        <div class="button-row">
          <button class="btn btn-primary" data-action="resume">繼續原任務</button>
          <button class="btn" data-action="force-start" data-mode="${mode}" data-unit="${unitId || ''}" data-subject="${subject || ''}" data-difficulty="${difficulty || ''}">開始新任務</button>
        </div>
      `);
      return;
    }
    let qs, reviewTargets;
    try {
      if (mode === 'review') {
        const plan = E.reviewPlan(ctx.state, bank);
        qs = plan.questions;
        reviewTargets = plan.targets;
      } else qs = E.select(bank, { mode, unitId, subject, difficulty, state: ctx.state });
    } catch (e) {
      toast(e.message);
      return;
    }
    if (!qs.length) {
      toast(mode === 'review' ? '目前沒有待加強或到期複習題目。' : '題庫尚未準備完成。');
      return;
    }
    closeModal();
    ctx.state.active = {
      id: crypto.randomUUID ? crypto.randomUUID() : 'r' + Date.now() + Math.random().toString(36).slice(2),
      mode,
      questionRevision: E.questionRevision,
      unitId,
      subject,
      difficulty: difficulty || null,
      questionIds: qs.map(q => q.id),
      ...(reviewTargets ? { reviewTargets } : {}),
      answers: {},
      startedAt: Date.now()
    };
    save();
    go('quiz');
  }

function updateQuizStatus() {
    const run = ctx.state.active;
    if (!run) return;
    const qs = runQuestions(), count = qs.filter(q => E.hasAnswer(q, run.answers[q.id])).length;
    const counter = document.getElementById('answered-count');
    if (!counter) return;
    counter.textContent = count;
    const note = document.getElementById('submit-note');
    if (note) note.textContent = count === qs.length ? '全部完成，準備查看你的任務報告' : '還有' + (qs.length - count) + '題等待你的決定';
    const subBtn = document.getElementById('submit-run');
    if (subBtn) subBtn.disabled = count !== qs.length;
    qs.forEach((q, index) => {
      const dot = document.querySelector(`[data-qdot="${q.id}"]`);
      const answered = E.hasAnswer(q, run.answers[q.id]);
      dot?.classList.toggle('done', answered);
      dot?.setAttribute('aria-label', `第 ${index + 1} 題，${answered ? '已作答' : '未作答'}`);
    });
  }

function submit(auto = false) {
    if (!ctx.canEdit()) return;
    const run = ctx.state.active;
    if (!run) return;
    if (!auto && !runQuestions().every(q => E.hasAnswer(q, run.answers[q.id]))) {
      toast('請先完成所有題目，再提交任務。');
      return;
    }
    const result = E.grade(ctx.state, run, bank);
    ctx.state = result.state;
    ctx.lastReport = result.report;
    save();
    closeModal();
    go('result', result.report.runId);
    if (auto) toast('模擬時間到，已自動交卷。');
  }

function tick() {
    const run = ctx.state.active;
    if (!run || run.mode !== 'exam') return;
    const remaining = Math.max(0, 75 * 60 - Math.floor((Date.now() - run.startedAt) / 1000));
    const clock = document.getElementById('clock');
    if (clock) {
      clock.querySelector('span').textContent = String(Math.floor(remaining / 60)).padStart(2, '0') + ':' + String(remaining % 60).padStart(2, '0');
      clock.classList.toggle('urgent', remaining < 300);
    }
    if (remaining === 0) submit(true);
  }
return { runQuestions, start, updateQuizStatus, submit, tick };
}
window.FactorySession = { create };
})();
;
/* Source: progress-store.js */
(function () { 'use strict';
function create(ctx) {
const { E, bank, save, toast, modal, closeModal, icon, go } = ctx;
function exportProgress() {
    const payload = { ...ctx.state, exportedAt: new Date().toISOString() };
    const url = URL.createObjectURL(new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'factory-quest-progress-' + E.dateKey() + '.json';
    a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    toast('進度備份已匯出。');
  }
  const importInput = document.createElement('input');
  importInput.type = 'file';
  importInput.accept = '.json,application/json';
  importInput.hidden = true;
  document.body.appendChild(importInput);
  importInput.addEventListener('change', async () => {
    const f = importInput.files[0];
    if (!f) return;
    try {
      if (f.size > 2000000) throw new Error('備份檔案太大，請選擇本網站匯出的進度。');
      const raw = JSON.parse(await f.text());
      if (!raw || raw.version !== 1 || !Array.isArray(raw.earnedCorrectIds) || !raw.best || typeof raw.best !== 'object' || Array.isArray(raw.best) || !Array.isArray(raw.history)) throw new Error('這不是有效的智造闖關進度檔。');
      const incoming = E.restore(raw, bank);
      modal(`
        <button class="modal-close" data-action="close" aria-label="關閉">${icon('cross')}</button>
        <h2>匯入這份學習進度？</h2>
        <p>備份包含${incoming.passedUnits.length}個已通關部門與${incoming.xp} XP。匯入後會取代目前裝置的進度。</p>
        <div class="button-row">
          <button class="btn btn-primary" id="confirm-import">匯入並取代</button>
          <button class="btn" data-action="close">保留目前進度</button>
        </div>
      `);
      document.getElementById('confirm-import').addEventListener('click', () => {
        if (!ctx.canEdit()) return;
        ctx.state = incoming;
        ctx.lastReport = null;
        save();
        closeModal();
        go('progress');
        toast('進度已匯入。');
      });
    } catch (e) {
      toast(e.message || '無法讀取進度備份。');
    }
    importInput.value = '';
  });


return { exportProgress, importInput };
}
window.FactoryProgressStore = { create };
})();
;
/* Source: controls.js */
(function () { 'use strict';
function bind(ctx) {
const { go, save, render, icon, esc, E, DATA, qmap, toast, modal, closeModal, poster, lightbox, openInteractive, openQuizHelper, start, updateQuizStatus, submit, exportProgress, importInput } = ctx;
document.addEventListener('click', e => {
    const b = e.target.closest('[data-action]');
    if (!b || b.disabled) return;
    // Safari pointer activation does not focus buttons before opening a dialog.
    b.focus({ preventScroll: true });
    const a = b.dataset.action;
    switch (a) {
      case 'skip':
        e.preventDefault();
        document.getElementById('content').focus();
        break;
      case 'nav':
        closeModal();
        go(b.dataset.view);
        break;
      case 'unit':
        go('unit', b.dataset.unit);
        break;
      case 'filter':
        ctx.filter = b.dataset.filter === 'all' ? 'all' : Number(b.dataset.filter);
        render();
        break;
      case 'poster':
        poster(b.dataset.unit);
        break;
      case 'poster-file':
        lightbox(b.dataset.file, b.dataset.title || '分解結構圖');
        break;
      case 'lightbox':
        lightbox(b.dataset.src, b.dataset.title || '圖解檢視');
        break;
      case 'open-interactive':
        openInteractive(b.dataset.url, b.dataset.title || '互動式架構圖');
        break;
      case 'quiz-helper':
        openQuizHelper(b.dataset.unit);
        break;
      case 'exam-tab':
        go('exam', b.dataset.tab || 'quiz');
        break;
      case 'guide-tab':
        go('guide', b.dataset.tab, b.dataset.subtab || '');
        break;
      case 'reading-section': {
        e.preventDefault();
        const heading = document.getElementById(b.dataset.target);
        const disclosure = b.closest('details');
        if (disclosure && !window.matchMedia?.('(min-width: 1360px)').matches) disclosure.open = false;
        ctx.readingPosition.jump(heading);
        break;
      }
      case 'clear-library':
        window.FactoryGuide.filterCatalog(true);
        break;
      case 'question-open':
        if (!e.ctrlKey && !e.metaKey && !e.shiftKey && !e.altKey) window.FactoryQuestions.remember(b.dataset.question, b.dataset.material);
        break;
      case 'question-return':
        window.FactoryQuestions.returnTo(b.dataset.question, b.dataset.material);
        break;
      case 'question-clear':
        window.FactoryQuestionCatalog.update(true);
        break;
      case 'question-page':
        window.FactoryQuestionCatalog.paginate(Number(b.dataset.page));
        break;
      case 'close':
        closeModal();
        break;
      case 'retry-media':
        window.FactoryMedia.retry(b.closest('dialog') || document.getElementById('content'));
        break;
      case 'start':
        start(b.dataset.mode, b.dataset.unit || null, Number(b.dataset.subject) || null, false, b.dataset.difficulty || null);
        break;
      case 'force-start':
        start(b.dataset.mode, b.dataset.unit || null, Number(b.dataset.subject) || null, true, b.dataset.difficulty || null);
        break;
      case 'resume':
        closeModal();
        go('quiz');
        break;
      case 'review':
        start('review');
        break;
      case 'jump': {
        const question = document.getElementById('question-' + b.dataset.q);
        question?.scrollIntoView({ behavior: window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth', block: 'start' });
        question?.querySelector('h2')?.focus({ preventScroll: true });
        break;
      }
      case 'report':
        go('result', b.dataset.id);
        break;
      case 'export':
        exportProgress();
        break;
      case 'import':
        importInput.click();
        break;
      case 'reset':
        modal(`
          <button class="modal-close" data-action="close" aria-label="關閉">${icon('cross')}</button>
          <h2>要讓工廠重新開始嗎？</h2>
          <p>目前裝置的徽章、經驗、成績與未完成作答都會清除。建議先匯出進度備份。</p>
          <div class="button-row">
            <button class="btn btn-danger" data-action="confirm-reset">清除並重新開始</button>
            <button class="btn" data-action="close">保留進度</button>
          </div>
        `);
        break;
      case 'confirm-reset':
        if (!ctx.canEdit()) return;
        ctx.state = E.emptyState();
        ctx.lastReport = null;
        save();
        closeModal();
        go('home');
        toast('已重新開始。');
        break;
    }
  });
document.addEventListener('change', e => {
    if (['exam-question-subject', 'exam-question-notes'].includes(e.target.id)) window.FactoryQuestionCatalog.update();
    if (e.target.id === 'exam-question-jump') go('guide', 'questions', e.target.value);
    if (e.target.id === 'library-group') window.FactoryGuide.filterCatalog();
    if (e.target.id === 'result-only-wrong') {
      document.querySelectorAll('.feedback-card.right').forEach(card => { card.hidden = e.target.checked; });
      const total = document.querySelectorAll('.feedback-card:not([hidden])').length;
      document.getElementById('result-count').textContent = `顯示 ${total} 題解析`;
    }
  });
document.addEventListener('input', e => {
    if (e.target.id === 'exam-question-search') { window.FactoryQuestionCatalog.update(); return; }
    if (e.target.id === 'library-search') {
      window.FactoryGuide.filterCatalog();
      return;
    }
    if (e.target.id === 'glossary-input') {
      ctx.guideSearch = e.target.value;
      window.FactoryGuide.updateGlossary(DATA, ctx.guideSearch, esc);
      return;
    }
    const id = e.target.dataset.answer;
    if (!id || !ctx.state.active) return;
    if (!ctx.canEdit()) return;
    const q = qmap.get(id);
    if (!q) return;
    ctx.state.active.answers[id] = q.kind === 'choice' ? Number(e.target.value) : e.target.value;
    if (q.kind === 'number') ctx.saveSoon();
    else save();
    const err = document.getElementById('error-' + id);
    if (err) err.textContent = String(e.target.value).trim() && E.parseNumber(e.target.value) === null ? '請輸入數字；單位已標示在右側。' : '';
    updateQuizStatus();
  });
document.addEventListener('submit', e => {
    if (e.target.id === 'quiz-form') {
      e.preventDefault();
      submit();
    }
  });
}
window.FactoryControls = { bind };
})();
;
